-- =====================================================================
-- 490_tprm_menu_dashboard_rollback.sql
--
-- Reverses 490 (menu + dashboard).
--   Drops sp_dashboard_tprm; removes the Third-Party Risk menu rows
--   (nav-tprm and its five children) and their permission rows.
--
-- Turn the API / Web change off first (or deploy the previous build): the
-- TPRM screens call the procedures this drops. Roll back in reverse
-- order: 490, 489, 488, 487, 486.
-- Generated by tools/tprm/gen_rollbacks.py from the objects 490 creates.
-- SAFE TO RE-RUN. ASCII-only.
-- =====================================================================
SET NOCOUNT ON;
SET XACT_ABORT ON;
SET NOEXEC OFF;
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

DROP PROCEDURE IF EXISTS grac_practice.sp_dashboard_tprm;
GO

-- Menu rows and their permission rows (children first, then the root).
DELETE p
  FROM grac_practice.organization_role_menu_permission p
  JOIN grac_practice.menu_master m ON m.menu_id = p.menu_id
 WHERE m.menu_key IN (N'tprm-dashboard', N'tprm-third-parties', N'tprm-engagements', N'tprm-reviews', N'tprm-configuration', N'nav-tprm');
PRINT CONCAT('490 rollback: permission rows removed: ', @@ROWCOUNT);
DELETE FROM grac_practice.menu_master
 WHERE menu_key IN (N'tprm-dashboard', N'tprm-third-parties', N'tprm-engagements', N'tprm-reviews', N'tprm-configuration');
DELETE FROM grac_practice.menu_master WHERE menu_key = N'nav-tprm';
PRINT '490 rollback: menu rows removed. Also remove the 490 rows from 274_menu_master_seed.sql.';
GO

PRINT '490 rollback complete.';
GO
